sp_widget.client_script:
api.controller=function($scope, spUtil, $rootScope) {
	/* widget controller */
	var c = this;
	try{
		c.currentEncounter = '';
		c.isLoading = false;
		c.viewAdversariesToAdd = false;
		c.showFullAdversaryDetail = false;
		c.currentAdversary = '';
		c.showAllSkills = true;

		$scope.selectEncounter = function(encounter){
			c.currentEncounter = encounter;
			c.server.get({action: 'fetchEncounterAdversaries', encounter: encounter}).then(function(response){
				$scope.data = response.data;
				c.isLoading = false;
			});
		}

		$scope.openForm = function(adversary, view){
			var params = {
				table: 'x_176383_star_wars_encounter_adversary',
				sys_id: adversary.sys_id,
				view: view
			};
			spUtil.get('widget-form', params).then(function(response){
				$scope.data.widget = response;
				c.editAdversary = true;
			});
		}

		$scope.fetchAdversaries = function(){
			c.server.get({action: 'fetchAdversaries'}).then(function(response){
				$scope.data.adversariesList = response.data.adversariesList;
				console.log($scope.data.adversariesList);
			});
		}

		$rootScope.$on('sp.form.submitted', function(){
			$scope.selectEncounter(c.currentEncounter);
			c.editAdversary = false;
			$scope.buildDiceRolls(c.currentAdversary);
		});

		//build roll visual
		$scope.buildDiceRolls = function(adversary){
			if(c.showFullAdversaryDetail){
				setTimeout(function(){
					//build skill rolls
					for(var i = 0; i < adversary.skills.length; i++){
						var parentElement = document.getElementById(adversary.skills[i].sysID);
						var childElement = document.createElement("a");
						parentElement.appendChild(childElement);
						var abilityDice = 0;
						var proficiencyDice = 0;

						if(adversary.skills[i].ranks != adversary.characteristics[adversary.skills[i].characteristic.toLowerCase()]){
							if(adversary.skills[i].ranks > adversary.characteristics[adversary.skills[i].characteristic.toLowerCase()]){
								abilityDice = adversary.skills[i].ranks - adversary.characteristics[adversary.skills[i].characteristic.toLowerCase()];
								proficiencyDice = adversary.characteristics[adversary.skills[i].characteristic.toLowerCase()];
							} else{
								abilityDice = adversary.characteristics[adversary.skills[i].characteristic.toLowerCase()] - adversary.skills[i].ranks;
								proficiencyDice = adversary.skills[i].ranks;
							}

							for(var j = 0; j < abilityDice; j++){
								var icon = document.createElement("i");
								icon.classList.add('fas', 'fa-dice-d8', 'ability-dice', 'dice');
								childElement.appendChild(icon);
							}
						} else{
							proficiencyDice = adversary.skills[i].ranks;
						}
						for(var j = 0; j < proficiencyDice; j++){
							var icon = document.createElement("i");
							icon.classList.add('fas', 'fa-dice-d12', 'proficiency-dice', 'dice');
							childElement.appendChild(icon);
						}
					}

					//build weapon rolls
					adversary.combat.weapons.forEach(function(weapon){
						var weaponParentElement = document.getElementById(weapon.sys_id);
						var weaponChildElement = document.createElement("b");
						weaponParentElement.appendChild(weaponChildElement);
						var weaponAbilityDice = 0;
						var weaponProficiencyDice = 0;

						adversary.skills.forEach(function(skill){
							if(skill.sysID == weapon.skill.sysID){
								if(skill.ranks != adversary.characteristics[skill.characteristic.toLowerCase()]){
									if(skill.ranks > adversary.characteristics[skill.characteristic.toLowerCase()]){
										weaponAbilityDice = skill.ranks - adversary.characteristics[skill.characteristic.toLowerCase()];
										weaponProficiencyDice = adversary.characteristics[skill.characteristic.toLowerCase()];
									} else{
										weaponAbilityDice = adversary.characteristics[skill.characteristic.toLowerCase()] - skill.ranks;
										weaponProficiencyDice = skill.ranks;
									}

									for(var j = 0; j < weaponAbilityDice; j++){
										var icon = document.createElement("i");
										icon.classList.add('fas', 'fa-dice-d8', 'ability-dice', 'dice');
										weaponChildElement.appendChild(icon);
									}
								} else{
									weaponProficiencyDice = skill.ranks;
								}

								for(var j = 0; j < weaponProficiencyDice; j++){
									var icon = document.createElement("l");
									icon.classList.add('fas', 'fa-dice-d12', 'proficiency-dice', 'dice');
									weaponChildElement.appendChild(icon);
								}
							}
						});
					});
				}, 500);
			}
		}

	} catch(e){
		alert(e.message);
	}
};

sp_widget.css:
.encounters-list-container{
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: flex-start;
  align-items: center;
  column-gap: 1.5rem;

  .encounter-card{
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    background-color: #000;
    padding: 2rem;
    border: .1rem solid #e21414;
    border-radius: 2rem;
    row-gap: 1rem;

    .card-header{
      display: flex;
      flex-direction: column;
      align-items: center;
      font-size: 1.6rem;
      font-weight: bold;
    }

    .card-body{
      display: flex;
      flex-direction: column;
      align-items: center;
    }

    .card-buttons-container{
      .card-button{
        background: transparent;
        border-radius: 2rem;
        padding: .5rem 1rem;

        &:hover{
          box-shadow: 0 0 .8rem silver;
        }
      }
    }
  }
}

//encounter detail styling
.encounter-detail-container{
  display: flex;
  flex-direction: column;
  padding-left: 2rem;
  padding-right: 2rem;
  row-gap: 2rem;

  .encounter-header-buttons-container{
    display: flex;
    align-items: center;
    justify-content: space-between;

    .back-button-container{
      .fa-starfighter{
        transform: rotate(270deg);
        font-size: 3rem;
        color: #e21414;
      }
    }

    .add-adversaries-button-container{
      .fa-user-bounty-hunter{
        font-size: 3rem;
        color: #e21414;
      }
    }
  }

  .encounter-adversaries-cards-body-container{
    display: flex;
    align-items: stretch;
    justify-content: space-evenly;

    .ability-dice{
      color: green;
    }

    .proficiency-dice{
      color: yellow;
    }

    .encounter-adversary-card{
      display: flex;
      flex-direction: column;
      align-items: center;
      row-gap: 2rem;
      background: black;
      padding: 1rem;
      border-radius: 2rem;
      border: .1rem solid #e21414;

      .encounter-adversary-card-header{
        display: flex;
        flex-direction: column;
        align-items: center;
        font-weight: bold;

        .name{
          font-size: 1.8rem;
        }
      }

      .encounter-adversary-characteristics-container{
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        align-items: center;
        justify-content: space-evenly;
        width: 100%;
        column-gap: 1rem;

        .encounter-adversary-characteristic{
          display: flex;
          flex-direction: column;
          align-items: center;
          border: .1rem solid #e21414;
          border-radius: .8rem;
          justify-content: space-between;

          .encounter-adversary-characteristic-value{
            order: 0;
            width: 100%;
            text-align: center;
            color: black;
            background-color: #fff;
            padding: .5rem 0;
            border-radius: .8rem .8rem 0 0;
            font-weight: 600;
          }

          .encounter-adversary-characteristic-label{
            order: 1;
            width: 100%;
            background-color: #e21414;
            padding: 0.3rem 1rem;
            border-radius: 0 0 .8rem .8rem;
          }
        }
      }

      .wound-strain-defense-container{
        display: flex;
        align-items: center;
        justify-content: space-evenly;
        flex-direction: row;
        flex-wrap: nowrap;
        column-gap: 1rem;
        width: 100%;
        height: 100%;

        .combat-detail-tracker-container{
          display: flex;
          flex-direction: column;
          align-items: center;
          background-color: #fff;
          justify-content: flex-start;
          border-radius: 2rem;
          height: 100%;

          .combat-detail-tracker-label{
            background-color: #2f3860;
            padding: .4rem 1.5rem;
            border-radius: 2rem;
          }

          .combat-detail-tracker-values{
            display: flex;
            flex-direction: row;
            align-items: center;
            color: #000;

            .combat-detail{
              display: flex;
              flex-direction: column;
              align-items: center;

              .combat-detail-value{
                font-size: 1.6rem;
                padding: .5rem;
              }
            }

            .combat-detail-label{
              padding: .5rem 1rem;
              color: #fff;
            }

            .threshold-container{
              border-right: .1rem solid darkgray;

              .threshold-label{
                background-color: #e21414;
                border-radius: 0 0 0 2rem;
              }
            }

            .current-container{
              .current-label{
                background-color: #1933f4;
                border-radius: 0 0 2rem 0;
              }
            }
          }
        }
      }

      .edit-buttons-container{
        width: 100%;
        display: flex;
        flex-direction: row;
        align-items: center;
        justify-content: space-evenly;

        .edit-adversary-button{
          background: transparent;
          border-radius: 2rem;
          padding: .5rem 1rem;

          &:hover{
            box-shadow: 0 0 .8rem silver;
          }
        }
      }

      .full-adversary-detail-container{
        width: 100%;
        display: flex;
        flex-direction: column;
        align-items: center;
        row-gap: 2rem;

        .full-detail-section{
          display: flex;
          flex-direction: column;
          align-items: center;
          row-gap: 1rem;
          width: 100%;

          .full-detail-section-header{
            display: flex;
            flex-direction: column;
            align-items: center;

            .section-header{
              font-size: 1.8rem;
              font-weight: bold;
            }

            .toggle-all-skills{
              background: transparent;
              border-radius: 2rem;
              padding: .5rem 1rem;

              &:hover{
                box-shadow: 0 0 .8rem silver;
              }
            }
          }

          .description{
            width: 100%;
          }
        }
      }
    }
  }
}

//edit adversary flyout
.encounter-flyout-container{
  position: fixed;
  top: 10%;
  width: 90%;
  left: 5%;
  max-height: 70rem;
  background-color: #000;
  border: .1rem solid #e21414;
  border-radius: 2rem;
  padding: 2rem;
  overflow-y: scroll;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  row-gap: 2rem;

  .close-button{
    text-align: right;
    font-size: 2rem;
    color: #e21414;
  }
}

sp_widget.script:
(function() {
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */
try{
	var util = new starWarsGMUtil();
	var campaignId = $sp.getParameter('campaign');
	data.encounters = util.getCampaignEncounters(campaignId);
	console.log(data.encounters);

	if(input){
		if(input.action == 'fetchEncounterAdversaries'){
			data.encounterAdversaries = util.getEncounterAdversaries(input.encounter.sys_id);
		} else if(input.action == 'fetchAdversaries'){
			data.adversariesList = util.fetchAdversaries();
		}
	}
} catch(e){
	console.log('error in star wars encounter builder widget - server side: ' + e.message);
}
})();
